/**
 * @brief 处理 AP 发往 TH (dst=0x03) 的级联转发请求帧，严格保护在途关联状态不被覆盖
 * @param frame 完整请求帧指针
 * @param len 帧总长度
 */
static void handle_th_relay_req(const uint8_t *frame, uint16_t len)
{
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    if (frame[6] <= 1U)
    {
        mc_dbg_log_frame_err(frame, "BAD_FRAME", 0x05U);
        return;
    }
    if (s_relay_pending)
    {
        mc_dbg_log_tx_err("TH", seq, cmd_id);
        return;
    }
    const bool enter_proxy = ((cmd_id >= MINIMC_CMD_OTA_START) && (cmd_id <= MINIMC_CMD_OTA_STATUS)) ||
                             ((cmd_id == MINIMC_CMD_SYSTEM_CONTROL) && (len >= 16U) && (frame[12] == 2U));
    if (enter_proxy)
    {
        s_th_proxy_active = true;
        s_th_proxy_last_ms = wk_timebase_get();
        forward_uart_mode_set(FORWARD_UART_MODE_OTA_ROUTE);
    }
    uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
    relay_frame(frame, len, relay_buf);
    if (!forward_uart_send_raw(relay_buf, len))
    {
        mc_dbg_log_tx_err("TH", seq, cmd_id);
        return;
    }
    s_relay_pending = true;
    s_relay_from_mc_local = false;
    s_relay_seq = seq;
    s_relay_seq16 = seq;
    s_relay_cmd = cmd_id;
    s_relay_start_ms = wk_timebase_get();
    if (s_th_proxy_active) { s_th_proxy_last_ms = s_relay_start_ms; }
    s_relay_timeout_ms = get_th_relay_timeout_ms(cmd_id);
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq, cmd_id, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
}

/**
 * @brief 处理从 AP (USART2) 接收并通过 CRC16 校验的完整协议帧
 * @param frame 完整请求帧指针
 * @param len 帧总长度
 */
static void handle_ap_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    const uint8_t dst_id = frame[3];
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    char rx_kv[48];
    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u", (unsigned int)len);
    const mc_dbg_meta_t rx_meta = { "RX", mc_dbg_node_name(dst_id), seq, cmd_id, "OK" };
    mc_dbg_emit(&rx_meta, rx_kv);

    if (s_th_proxy_active && (!is_ota_or_maint_cmd(cmd_id)))
    s_relay_from_mc_local = true;
    s_relay_seq = seq;
    s_relay_seq16 = seq;
    s_relay_cmd = MINIMC_CMD_GCODE_EXEC;
    s_relay_start_ms = wk_timebase_get();
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq, MINIMC_CMD_GCODE_EXEC, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
    return true;
}

/**
 * @brief 检查在途 TH 级联请求超时与 5000ms 代理模式无活动自动恢复（含 32 位模半空间防时基下溢保护）
 * @param now_ms 当前系统毫秒计数
 */
static void check_th_relay_timeout(uint32_t now_ms)
{
    /* 防御层二: 采用 < 0x80000000UL 半空间判据过滤 now_ms < start_ms 的无符号减法下溢 (0xFFFFFFFFU) */
    const uint32_t proxy_elapsed = (uint32_t)(now_ms - s_th_proxy_last_ms);
    if (s_th_proxy_active && (proxy_elapsed < 0x80000000UL) &&
        (proxy_elapsed >= MC_TH_PROXY_TIMEOUT_MS))
    {
        s_th_proxy_active = false;
        forward_uart_mode_set(FORWARD_UART_MODE_NORMAL);
    }
    if (!s_relay_pending)
    {
        return;
    }
    const uint32_t elapsed = (uint32_t)(now_ms - s_relay_start_ms);
    if ((elapsed >= 0x80000000UL) || (elapsed < s_relay_timeout_ms))
    {
        return;
    }
    s_relay_pending = false;
    s_relay_from_mc_local = false;
    char kv[64];
    (void)snprintf(kv, sizeof(kv), "elapsed_ms=%lu err_code=0x03", (unsigned long)elapsed);
    const mc_dbg_meta_t rrx_meta = { "RELAY_RX", "TH", s_relay_seq, s_relay_cmd, "TIMEOUT" };
    const mc_dbg_meta_t err_meta = { "ERR", "TH", s_relay_seq, s_relay_cmd, "TIMEOUT" };
    mc_dbg_emit(&rrx_meta, kv);
    mc_dbg_emit(&err_meta, kv);
}

