 * @param now_ms 当前系统毫秒计数
 */
void mc_debug_log_periodic_state(uint32_t now_ms)
{
    if (!s_mc_dbg_enabled)
    {
        return;
    }
    if (s_state_log_init && ((uint32_t)(now_ms - s_last_state_log_ms) < MC_DBG_STATE_INTERVAL_MS))
    {
        return;
    }
    s_last_state_log_ms = now_ms;
    s_state_log_init = true;

    mc_dbg_sync_runtime_state();
    char kv[128];
    mc_dbg_format_temp_kv(kv, sizeof(kv));
    const mc_dbg_meta_t temp_meta = { "STATE", "MC", s_dbg_state.ack_seq, MINIMC_CMD_GET_TEMP, "OK" };
    mc_dbg_emit(&temp_meta, kv);

    mc_dbg_format_job_kv(kv, sizeof(kv));
    const mc_dbg_meta_t job_meta = { "STATE", "MC", s_dbg_state.ack_seq, MINIMC_CMD_JOB_CONTROL, "OK" };
    mc_dbg_emit(&job_meta, kv);
}

/**
 * @brief 从 AP 接收环形队列按 600B 预算拉取字节并推进流式帧解析器
 */
static void drain_ap_rx(void)
{
    uint8_t byte = 0U;
    uint16_t budget = 600U;
    while ((budget > 0U) && ring_pop(&s_ap_ring, &byte))
    {
        budget--;
        bool frame_ready = false;
        if (parser_step(&s_ap_parser, byte, &frame_ready) && frame_ready)
        {
            const uint16_t plen = (uint16_t)s_ap_parser.buf[10] | (uint16_t)((uint16_t)s_ap_parser.buf[11] << 8U);
            const uint16_t f_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
            handle_ap_frame(s_ap_parser.buf, f_len);
        }
    }
}

/**
 * @brief 从 USART6 (MC↔TH 级联链路) 读取接收字节并推进流式帧解析器（扩容至 534B）
 */
static void drain_th_rx(void)
{
    if (forward_uart_rx_poll() != 0U)
    {
        uint8_t th_buf[MINIMC_MAX_FRAME_SIZE];
        const uint16_t th_len = forward_uart_proto_rx_read(th_buf, sizeof(th_buf));
        for (uint16_t i = 0U; i < th_len; ++i)
        {
            bool frame_ready = false;
            if (parser_step(&s_th_parser, th_buf[i], &frame_ready) && frame_ready)
            {
                const uint16_t plen = (uint16_t)s_th_parser.buf[10] | (uint16_t)((uint16_t)s_th_parser.buf[11] << 8U);
                const uint16_t f_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
                handle_th_frame(s_th_parser.buf, f_len);
            }
        }
    }
}

/**
 * @brief 主循环非阻塞协议与调试排空轮询入口（先排空收发再采样时基以消除同轮跨毫秒下溢）
 */
void minimc_proto_poll(void)
{
    /* 防御层一: 先执行 AP/TH 收发排空，再采样当前毫秒时基，确保 now_ms 不早于同轮更新的起始时间戳 */
    drain_ap_rx();
    drain_th_rx();
    const uint32_t now_ms = wk_timebase_get();
    check_th_relay_timeout(now_ms);
    mc_debug_log_periodic_state(now_ms);
    mc_debug_poll_drain();
}

/**
 * @brief 将 USART2 DMA/IDLE 中断接收的原始字节压入主循环无锁环形队列
 * @param data 接收字节流指针
 * @param len 字节数
 */
void minimc_proto_push_ap_rx(const uint8_t *data, uint16_t len)
{
    if ((data == NULL) || (len == 0U))
    {
        return;
    }
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_state == TH_UPG_STATE_START_HANDSHAKE, "BOOT_MODE verified -> START_HANDSHAKE");
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_ACK, 0x0803U, 4U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_last_th_tx_len == 158U && s_last_th_tx[5] == MINIMC_CMD_OTA_START && s_state == TH_UPG_STATE_STREAM_CHUNKS, "0x20 144B sent");
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_ACK, 0x0804U, 4U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_last_th_tx[5] == MINIMC_CMD_OTA_DATA && s_state == TH_UPG_STATE_STREAM_CHUNKS, "0x21 chunk 0 sent");
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_state == TH_UPG_STATE_FINISH, "all chunks streamed -> FINISH");
    inject_th_resp(MINIMC_NODE_MC, MINIMC_CMD_ACK, 0x0805U, 4U);
    th_upgrade_mgr_poll(s_mock_tick_ms);
    require_true(s_last_th_tx[5] == MINIMC_CMD_OTA_FINISH && s_state == TH_UPG_STATE_SUCCESS, "0x22 sent -> SUCCESS");
}

